"""把 Agent Core 事件转换为稳定的网络事件协议。"""

from datetime import datetime
from typing import Any
from zoneinfo import ZoneInfo

from ...events import (
    AgentEvent,
    ContextCompactionFailedEvent,
    ContextCompactionFinishedEvent,
