    PlanUpdatedEvent,
    RunFinishedEvent,
    TextDeltaEvent,
    ToolBatchFinishedEvent,
    ToolBatchStartedEvent,
    ToolExecutionCompletedEvent,
    ToolFinishedEvent,
    ToolStartedEvent,
)
