def serialize_agent_event(
    event: AgentEvent,
    *,
    run_id: str,
    stream_id: str,
    sequence: int,
    response_id: str | None = None,
) -> dict[str, Any] | None:
    """将 Core 事件转换为 Phase 3 允许公开的非权威流事件。"""
